{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례 별표 3상 해당재산가액 1,200만 원인 공원 부지에 가스관을 6개월 점용할 때 연간 요율과 6개월 점용료",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "가스관(수도관, 하수도관, 가스관, 지하에 설치하는 전선)의 점용료는 연액 기준으로 해당재산가액의 10/1,000이다. 해당재산가액이 1,200만 원이면 연간 요율은 1,200만 원 × 10/1,000 = 12만 원이다. 점용기간이 1년 미만인 월 단위 산정은 연액 × 점용월수/12이므로, 6개월 점용료는 12만 원 × 6/12 = 6만 원이다.",
          "b_ids": "도시공원:별표3#행1, 도시공원:제18조제3항, 도시공원:제18조제3항제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
